def is_valid(s: str) -> bool:
    # Define matching pairs
    matching = {')': '(', ']': '[', '}': '{'}

    # Initialize an empty stack
    stack = []

    for char in s:
        if char in matching.values() or char == '*':
            stack.append(char)
        elif char in matching:
            if not stack:
                return False

            top = stack.pop()

            if top != '*' and top != matching[char]:
                return False

            # Handle wildcards
            while stack and stack[-1] == '*':
                if (top == '(' and char == ')') or \
                   (top == '[' and char == ']') or \
                   (top == '{' and char == '}'):
                    stack.pop()
                    break
                else:
                    top = stack.pop()

    # Ensure all remaining items in the stack are matched with wildcards
    while stack:
        if stack[-1] != '*':
            return False
        stack.pop()

    return True

# Example usage:
print(is_valid("(*)"))  # True
print(is_valid("(*))"))  # False
print(is_valid("((**))"))  # True
print(is_valid("([)]"))  # False
